<?php foreach(['supply'=>'Approvisionner un comptoir','return_cold'=>'Remettre au froid'] as $direction=>$drawerTitle):if($direction==='return_cold'&&$section!=='counters')continue;$drawerId=$direction==='supply'?'flow-supply':'flow-return';require __DIR__.'/drawer_start.php';$action='butchery/flow/movements';$confirm=$direction==='supply'?'Déplacer ces produits de la chambre froide vers le comptoir ?':'Remettre ces produits du comptoir en chambre froide ?';require __DIR__.'/form_start.php'; ?>
<input type="hidden" name="direction" value="<?=e($direction)?>"><div class="form-grid"><?php // Produits regroupés : somme des lots ; lots dans l’ordre de prélèvement (DLC la plus proche pour approvisionner, la plus lointaine pour remettre au froid).
$flowItems=[];foreach($direction==='supply'?$coldProducts:$finished as $r){if($r['expiry_date']<date('Y-m-d')||!in_array($r['status'],['available','reserved'],true))continue;$counted=isset($r['quantity_pieces']);$kgFree=(float)($direction==='supply'?$r['cold_available_kg']:$r['counter_kg']);$pcs=$counted?(int)($direction==='supply'?$r['cold_available_pieces']:$r['counter_pieces']):null;if(($counted?$pcs:$kgFree)<=0)continue;$id=(int)$r['item_id'];if(!isset($flowItems[$id]))$flowItems[$id]=['name'=>$r['item_name'],'kg'=>0.0,'pieces'=>$counted?0:null,'lots'=>[]];$flowItems[$id]['kg']=round($flowItems[$id]['kg']+$kgFree,3);if($counted)$flowItems[$id]['pieces']+=$pcs;$flowItems[$id]['lots'][]=['label'=>$r['lot_number'],'dlc'=>date('d/m/Y',strtotime($r['expiry_date'])),'expiry'=>$r['expiry_date'],'kg'=>$kgFree,'pieces'=>$pcs];}foreach($flowItems as&$fi)usort($fi['lots'],static fn($x,$y)=>$direction==='supply'?strcmp($x['expiry'],$y['expiry']):strcmp($y['expiry'],$x['expiry']));unset($fi);uasort($flowItems,static fn($x,$y)=>strcmp($x['name'],$y['name']));?><label class="form-wide"><span>Produit *</span><select name="item_id" required data-flow-item-select data-flow-order="<?=e($direction==='supply'?'DLC la plus proche en premier':'DLC la plus lointaine en premier')?>"><option value="">Choisir le produit</option><?php foreach($flowItems as $itemId=>$fi): ?><option value="<?=e($itemId)?>" data-max="<?=e($fi['kg'])?>"<?=$fi['pieces']!==null?' data-pieces="'.$fi['pieces'].'"':''?> data-lots="<?=e(json_encode($fi['lots']))?>"><?=e($fi['name'].' — '.($fi['pieces']!==null?$fi['pieces'].' pièce(s), ':'').number_format($fi['kg'],3,',',' ').' kg'.($direction==='supply'?' en chambre froide':' aux comptoirs').(count($fi['lots'])>1?' ('.count($fi['lots']).' lots)':''))?></option><?php endforeach; ?></select></label><label><span>Comptoir *</span><select name="counter_id" required><option value="">Choisir le comptoir</option><?php foreach($activeCounters as $c): ?><option value="<?=e($c['id'])?>"><?=e($c['name'])?></option><?php endforeach; ?></select></label><label data-flow-kg><span>Quantité (kg) *</span><input type="number" name="quantity_kg" min="0.001" step="0.001" required></label><label data-flow-pieces hidden><span>Nombre de pièces *</span><input type="number" name="quantity_pieces" min="1" step="1" inputmode="numeric" disabled></label></div><p class="livestock-guide" data-flow-preview aria-live="polite"></p><div class="exit-lots form-wide" data-flow-lots hidden><p class="exit-lots__title"><i class="bi bi-layers" aria-hidden="true"></i> <span data-flow-lots-title>Lots prélevés automatiquement</span></p><ul data-flow-lots-list></ul></div>
<?php $submitLabel=$direction==='supply'?'Approvisionner le comptoir':'Remettre en chambre froide';require __DIR__.'/form_end.php';require __DIR__.'/drawer_end.php';endforeach; ?>
